async function saveLicenseKey(){
  const publicKey=$('setting-license-key').value.trim();
  if(!publicKey){
    toast('Vlož veřejný Ed25519 klíč v PEM formátu.');
    return;
  }
  try{
    const response=await post('/api/workspace/settings',{
      workspace:settingsWorkspace,
      settings:{license_issuer_key:publicKey},
    });
    const value=await response.json();
    if(!response.ok){
      throw new Error(value.error||'Veřejný klíč nelze uložit.');
    }
    settingsWorkspace='';
    const selected=document.querySelector('input[name="workspace"]:checked')?.value;
    await refreshWorkspaceSettings(selected);
    toast('Licenční veřejný klíč byl nastaven');
  }catch(error){
    toast(error.message);
  }
}
