async function deleteFilePath(path,locked=false){let override=false;if(locked){override=confirm(`🔒 ${path} je chráněný.\n\nOpravdu odemknout a smazat?`);if(!override)return}else if(!confirm(`Smazat ${path}?`))return;try{const response=await post('/api/files/action',{operation:'delete',workspace:filesWorkspace(),path,override_locked:override}),value=await response.json();if(!response.ok)throw new Error(value.error||'Cestu nelze smazat.');toast(`${path} smazán`);await openFiles(filesPath)}catch(error){toast(error.message)}}
async function deleteOpenFile(){if(!selectedFile)return;const override=$('file-lock-override').querySelector('input').checked;if(selectedFile.locked&&!override)return toast('Nejdřív zapni override zámku.');if(!confirm(`Smazat ${selectedFile.path}?${selectedFile.locked?'\n\nChráněný soubor bude odemknut.':''}`))return;try{const response=await post('/api/files/action',{operation:'delete',workspace:filesWorkspace(),path:selectedFile.path,override_locked:override}),value=await response.json();if(!response.ok)throw new Error(value.error||'Soubor nelze smazat.');toast('Soubor smazán');await openFiles(filesPath)}catch(error){toast(error.message)}}
async function makeFileDirectory(){const name=prompt('Jméno nového adresáře:');if(!name)return;try{const response=await post('/api/files/action',{operation:'mkdir',workspace:filesWorkspace(),path:joinFilePath(filesPath,name)}),value=await response.json();if(!response.ok)throw new Error(value.error||'Adresář nelze vytvořit.');await openFiles(filesPath)}catch(error){toast(error.message)}}
async function uploadWorkspaceFile(file){if(!file)return;const path=joinFilePath(filesPath,file.name);try{const response=await fetch(`/api/files/upload?workspace=${encodeURIComponent(filesWorkspace())}&path=${encodeURIComponent(path)}`,{method:'POST',headers:{'X-Saslik-CSRF':csrf,'Content-Type':'application/octet-stream'},body:file}),value=await response.json();if(!response.ok)throw new Error(value.error||'Upload selhal.');toast(`${file.name} nahrán`);await openFiles(filesPath)}catch(error){toast(error.message)}}
function fileEditorDirty(){return !!selectedFile&&!$('file-content').disabled&&$('file-content').value!==fileLoadedContent}
function renderFileChange(){const indicator=$('file-change'),reload=$('file-reload'),dirty=fileEditorDirty();indicator.classList.toggle('hidden',!dirty&&!fileDiskChanged);indicator.classList.toggle('dirty',dirty);indicator.textContent=fileDiskChanged?(dirty?'● konflikt: disk změněn':'● změna na disku'):'● neuloženo';reload.classList.toggle('hidden',!selectedFile||(!dirty&&!fileDiskChanged))}
async function reloadOpenFile(initial=false){if(!selectedFile)return;const wasEditing=fileEditing;try{const response=await fetch(`/api/files/read?workspace=${encodeURIComponent(filesWorkspace())}&path=${encodeURIComponent(selectedFile.path)}`,{cache:'no-store'}),value=await response.json();if(!response.ok)throw new Error(value.error||'Soubor nelze otevřít.');renderFileContent(value.content);$('file-content').disabled=false;$('file-edit').disabled=false;$('file-save').disabled=false;$('file-close').disabled=false;fileLoadedContent=value.content;fileRevision=value.revision||'';fileDiskChanged=false;$('file-meta').textContent=selectedFile.locked?'text · chráněný soubor':'text · viewer · follow ready';setFileEditing(initial?false:wasEditing);renderFileChange()}catch(error){$('file-content').disabled=true;$('file-edit').disabled=true;$('file-save').disabled=true;$('file-meta').textContent=error.message;if(!initial){fileDiskChanged=true;renderFileChange()}}}
async function followFiles(){if(filesFollowBusy||!$('files-follow')?.checked||(!filesDetachedWindow&&activeTab!=='files'))return;filesFollowBusy=true;try{await openFiles(filesPath,true);if(!selectedFile||$('file-content').disabled)return;const response=await fetch(`/api/files/read?workspace=${encodeURIComponent(filesWorkspace())}&path=${encodeURIComponent(selectedFile.path)}`,{cache:'no-store'}),value=await response.json();if(!response.ok){fileDiskChanged=true;renderFileChange();return}if(value.revision===fileRevision)return;if(fileEditorDirty()){fileDiskChanged=true;renderFileChange();return}renderFileContent(value.content);fileLoadedContent=value.content;fileRevision=value.revision||'';fileDiskChanged=false;$('file-meta').textContent=`follow · obnoveno ${new Date().toLocaleTimeString()}`;renderFileChange()}catch{}finally{filesFollowBusy=false}}
function detachFiles(){if(filesDetachedWindow&&!filesDetachedWindow.closed)return attachFiles();const panel=document.getElementById('files'),popup=window.open('','saslik-files','popup,width=1180,height=760');if(!popup){toast('Browser zablokoval nové okno');return}filesDetachedWindow=popup;filesPlaceholder=document.createElement('section');filesPlaceholder.id='files';filesPlaceholder.className=`${panel.className} files-detached-placeholder`;filesPlaceholder.innerHTML='<div><b>Files běží v samostatném okně</b><button id="files-attach-here">Vrátit sem</button></div>';panel.replaceWith(filesPlaceholder);filesPlaceholder.querySelector('button').onclick=attachFiles;popup.document.open();popup.document.write(`<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Saslik · Files</title><link rel="stylesheet" href="${location.origin}${location.pathname.replace(/[^/]*$/,'')}style.css"><link rel="stylesheet" href="${location.origin}${location.pathname.replace(/[^/]*$/,'')}files.css"></head><body class="files-only"><main id="detached-files-root"></main></body></html>`);popup.document.close();popup.document.getElementById('detached-files-root').appendChild(panel);panel.classList.remove('hidden');$('files-detach').textContent='Vrátit do karty ↙';popup.onbeforeunload=()=>attachFiles(false);popup.focus()}
function attachFiles(closePopup=true){if(!filesDetachedWindow)return;const popup=filesDetachedWindow,panel=popup.closed?null:popup.document.getElementById('files');filesDetachedWindow=null;if(popup&&!popup.closed)popup.onbeforeunload=null;if(panel&&filesPlaceholder){filesPlaceholder.replaceWith(panel);panel.classList.toggle('hidden',activeTab!=='files');const button=panel.querySelector('#files-detach');if(button)button.textContent='Do okna ↗'}filesPlaceholder=null;if(closePopup&&popup&&!popup.closed)popup.close()}
$('files-up').onclick=()=>openFiles(filesPath.split('/').slice(0,-1).join('/'));
$('files-mkdir').onclick=makeFileDirectory;
$('files-upload').onclick=()=>$('files-upload-input').click();
$('files-upload-input').onchange=async event=>{await uploadWorkspaceFile(event.target.files[0]);event.target.value=''};
$('file-save').onclick=saveOpenFile;
$('file-delete').onclick=deleteOpenFile;
$('file-edit').onclick=()=>setFileEditing(true);
$('file-close').onclick=closeOpenFile;
$('file-content').oninput=()=>{updateFileHighlight();renderFileChange()};
$('file-content').onscroll=syncFileHighlightScroll;
$('file-reload').onclick=async()=>{if(fileEditorDirty()&&!confirm('Zahodit neuložené změny a načíst soubor z disku?'))return;await reloadOpenFile()};
