function devDiffClass(line){if(line.startsWith('+++ ')||line.startsWith('--- '))return'diff-file';if(line.startsWith('+'))return'diff-add';if(line.startsWith('-'))return'diff-del';if(line.startsWith('@@'))return'diff-hunk';if(line.startsWith('diff --git ')||line.startsWith('index ')||line.startsWith('new file ')||line.startsWith('deleted file '))return'diff-meta';return'diff-context'}
const devApiMarkup=`<section class="dev-api"><div class="dev-api-head"><span><b>API QUERIES</b><small>read-only dotazy na lokální komponenty labu</small></span><small id="dev-api-state">vyber dotaz</small></div><div class="dev-api-layout"><div class="dev-api-cards"><button type="button" data-dev-query="lored-stats"><b>Lored</b><span>GET /v1/stats</span></button><button type="button" data-dev-query="lored-health"><b>Lored</b><span>GET /readyz</span></button><button type="button" data-dev-query="sift-stats"><b>Sift</b><span>GET /api/stats</span></button><button type="button" data-dev-query="sift-diagnostics"><b>Sift</b><span>GET /api/diagnostics</span></button><button type="button" data-dev-query="sift-config"><b>Sift</b><span>GET /api/config</span></button></div><div class="dev-api-result"><div><code id="dev-api-title">výsledek</code><button id="dev-api-copy" type="button" disabled>Kopírovat</button></div><pre id="dev-api-output"><span class="muted">Dotaz se provede až kliknutím.</span></pre></div></div></section>`;
let devApiText='';
async function runDevApiQuery(button){document.querySelectorAll('[data-dev-query]').forEach(item=>item.classList.toggle('active',item===button));button.disabled=true;const state=$('dev-api-state'),output=$('dev-api-output');state.textContent='načítám…';state.className='';output.className='';output.textContent='Čekám na odpověď…';try{const response=await fetch(`/api/dev/query?name=${encodeURIComponent(button.dataset.devQuery)}`,{cache:'no-store'}),value=await response.json();if(!response.ok)throw new Error(value.error||`${value.label||'API'}: HTTP ${value.status||response.status}`);devApiText=value.kind==='json'?JSON.stringify(value.result,null,2):String(value.result??'');$('dev-api-title').textContent=`${value.label} · HTTP ${value.status} · ${value.elapsed_ms} ms`;output.textContent=devApiText||'(prázdná odpověď)';state.textContent='hotovo';state.className='ok';$('dev-api-copy').disabled=false}catch(error){devApiText='';$('dev-api-title').textContent=button.querySelector('b').textContent;output.textContent=error.message;output.className='error';state.textContent='chyba';state.className='error';$('dev-api-copy').disabled=true}finally{button.disabled=false}}
function initDevApi(){const dev=$('dev'),title=dev?.querySelector('.section-title');if(!dev||!title||dev.querySelector('.dev-api'))return;title.insertAdjacentHTML('afterend',devApiMarkup);dev.querySelectorAll('[data-dev-query]').forEach(button=>button.onclick=()=>runDevApiQuery(button));$('dev-api-copy').onclick=async()=>{await navigator.clipboard.writeText(devApiText);toast('Výsledek zkopírován')}}
function initDevPairing(){const dev=$('dev'),api=dev?.querySelector('.dev-api');if(!dev||!api||dev.querySelector('.dev-pairing'))return;api.insertAdjacentHTML('afterend','<details class="dev-pairing"><summary><span><b>SKEWER PAIRING</b><small>portal fingerprint a jednorázové přihlašovací údaje</small></span><i>›</i></summary><div><label>Portal SHA-256<code data-dev-portal-fingerprint>načítám…</code></label><label>Pairing link<code data-dev-pairing-link>zobrazí se pouze na vyžádání</code></label><span><button type="button" data-dev-pairing-load>Načíst tajný link</button><button type="button" data-dev-pairing-copy disabled>Kopírovat</button><button type="button" data-dev-pairing-rotate>Rotovat klíč</button></span></div></details>');const card=dev.querySelector('.dev-pairing'),fingerprint=card.querySelector('[data-dev-portal-fingerprint]'),link=card.querySelector('[data-dev-pairing-link]'),load=card.querySelector('[data-dev-pairing-load]'),copy=card.querySelector('[data-dev-pairing-copy]'),rotate=card.querySelector('[data-dev-pairing-rotate]');let secret='';card.ontoggle=async()=>{if(!card.open||fingerprint.dataset.loaded)return;try{const value=await(await fetch('/api/portal-tls',{cache:'no-store'})).json();fingerprint.textContent=value.fingerprint;fingerprint.dataset.loaded='1'}catch{fingerprint.textContent='nelze načíst'}};const fetchLink=async action=>{const response=await post('/api/skewer/pairing',{action,host:location.hostname.replace(/^\[|\]$/g,'')}),value=await response.json();if(!response.ok)throw new Error(value.error||'Pairing link nelze načíst.');secret=value.link;link.textContent=secret;copy.disabled=false};load.onclick=async()=>{load.disabled=true;try{await fetchLink('link')}catch(error){toast(error.message)}finally{load.disabled=false}};copy.onclick=async()=>{await navigator.clipboard.writeText(secret);toast('Pairing link zkopírován')};rotate.onclick=async()=>{if(!confirm('Zneplatnit dosud nevyměněný pairing link a vydat nový?'))return;rotate.disabled=true;try{await fetchLink('rotate');toast('Pairing klíč byl rotován')}catch(error){toast(error.message)}finally{rotate.disabled=false}}}
function updateDevHighlight(card){const textarea=card.querySelector('textarea'),highlight=card.querySelector('.dev-highlight');highlight.innerHTML=textarea.value.split('\n').map(line=>`<span class="${devDiffClass(line)}">${esc(line)||' '}</span>`).join('');highlight.scrollTop=textarea.scrollTop;highlight.scrollLeft=textarea.scrollLeft}
function updateDevLineNumbers(card){const textarea=card.querySelector('textarea'),lines=card.querySelector('.dev-lines'),count=textarea.value.split('\n').length;lines.textContent=Array.from({length:count},(_,index)=>index+1).join('\n');lines.scrollTop=textarea.scrollTop;updateDevHighlight(card)}
async function loadDevPatch(card,file){if(!file)return;const output=card.querySelector('output');if(file.size>1024*1024){output.textContent='Soubor je větší než 1 MiB.';output.className='error';return}try{card.querySelector('textarea').value=await file.text();updateDevLineNumbers(card);output.textContent=`načteno: ${file.name}`;output.className=''}catch(error){output.textContent=error.message;output.className='error'}}
async function devOperation(operation,extra={}){const response=await post('/api/dev/patch',{workspace:filesWorkspace(),operation,...extra}),value=await response.json();if(!response.ok)throw new Error(value.error||'Operace s patchem selhala.');dirtySources=value.source_changes||dirtySources;renderSourceRecovery(!!document.querySelector('.workspace-row.selected .workspace-state.running'));sourceStatusPollAt=0;void refreshComponentSourceStatuses(settingsWorkspace,true);renderDevPatches(value.patches||[]);return value}
async function applyDevPatch(card){const textarea=card.querySelector('textarea'),button=card.querySelector('[data-dev-apply]'),output=card.querySelector('output'),project=card.dataset.devProject,patch=textarea.value,name=card.querySelector('[data-dev-name]').value,alreadyApplied=card.querySelector('[data-dev-applied]').checked,operation=alreadyApplied?'remember-applied':'apply';if(!patch.trim()){output.textContent='Patch je prázdný.';output.className='error';return}button.disabled=true;button.textContent='Kontroluji…';output.textContent=alreadyApplied?'git apply -R --check':'git apply --check';output.className='';try{await devOperation(operation,{project,patch,name});output.textContent=alreadyApplied?'aplikovaný patch uložen pro revert':'patch aplikován a uložen';output.className='ok'}catch(error){output.textContent=error.message;output.className='error'}finally{button.disabled=false;button.textContent=alreadyApplied?'Uložit pro revert':'Aplikovat patch'}}
function renderDevPatches(patches){const target=$('dev-patch-history');if(!target)return;if(!patches.length){target.innerHTML='<span class="muted">Zatím žádné uložené patche.</span>';return}target.innerHTML=patches.map(patch=>`<article class="dev-journal-row ${patch.state}"><i></i><span><b>${esc(patch.name)}</b><small>${esc(patch.project)} · ${esc(patch.created_at||'')}</small></span><em>${patch.state==='applied'?'aplikovaný':'vrácený'}</em><button type="button" data-dev-journal-action="${patch.state==='applied'?'revert':'reapply'}" data-dev-patch-id="${esc(patch.id)}">${patch.state==='applied'?'Vrátit':'Znovu aplikovat'}</button></article>`).join('');target.querySelectorAll('[data-dev-journal-action]').forEach(button=>button.onclick=async()=>{const operation=button.dataset.devJournalAction,label=operation==='revert'?'Vrátit tento patch ze zdrojáků?':'Znovu aplikovat tento patch?';if(!confirm(label))return;button.disabled=true;try{await devOperation(operation,{id:button.dataset.devPatchId});toast(operation==='revert'?'Patch vrácen':'Patch znovu aplikován')}catch(error){toast(error.message)}finally{button.disabled=false}})}
async function refreshDevPatches(){try{const response=await fetch(`/api/dev/patches?workspace=${encodeURIComponent(filesWorkspace())}`,{cache:'no-store'}),value=await response.json();if(!response.ok)throw new Error(value.error||'Historii patchů nelze načíst.');renderDevPatches(value.patches||[])}catch(error){$('dev-patch-history').innerHTML=`<span class="error">${esc(error.message)}</span>`}}
function renderDevDebug(components,localClient=false){
 const target=$('dev-debug-components');if(!target)return;
 target.innerHTML=components.map(item=>`<article class="dev-debug-row ${item.active?'debugging':''} ${localClient?'':'remote'}"><i></i><span><b>${esc(item.component)}</b><small>${item.running?`PID ${esc(item.pid)}`:'neběží'}${item.active?` · gdbserver :${esc(item.port)}`:''}</small></span>${localClient?`<code>${esc(item.command||'debug binary není dostupná')}</code><button class="dev-icon-button" type="button" data-gdb-copy title="Kopírovat GDB příkaz" aria-label="Kopírovat GDB příkaz" ${item.available?'':'disabled'}>⧉</button>`:'<small class="dev-remote-note">GDB běží na hostu přes webovou konzoli</small>'}${item.active?'<button class="dev-icon-button" type="button" data-gdb-connect title="Otevřít GDB konzoli" aria-label="Otevřít GDB konzoli">›_</button>':''}<button class="dev-icon-button" type="button" data-gdb-action="${item.active?'stop':'start'}" title="${item.active?'Zastavit gdbserver':'Spustit gdbserver'}" aria-label="${item.active?'Zastavit gdbserver':'Spustit gdbserver'}" ${item.running&&item.available?'':'disabled'}>${item.active?'■':'▷'}</button></article>`).join('');
 target.querySelectorAll('.dev-debug-row').forEach((row,index)=>{
  const item=components[index],copy=row.querySelector('[data-gdb-copy]'),connect=row.querySelector('[data-gdb-connect]'),action=row.querySelector('[data-gdb-action]');
  if(copy)copy.onclick=async()=>{await navigator.clipboard.writeText(item.command);toast('GDB příkaz zkopírován')};
  if(connect)connect.onclick=()=>openGdbConsole(item.component);
  action.onclick=async event=>{
   const operation=event.currentTarget.dataset.gdbAction;
   if(operation==='start'&&!confirm(`Připojit gdbserver ke ${item.component} (PID ${item.pid})? Proces se pozastaví, dokud se nepřipojí GDB.`))return;
   event.currentTarget.disabled=true;
   try{const response=await post('/api/dev/debug',{workspace:filesWorkspace(),component:item.component,operation}),value=await response.json();if(!response.ok)throw new Error(value.error||'GDB operace selhala.');renderDevDebug(value.components||[],!!value.local_client);toast(operation==='start'?'gdbserver čeká na GDB':'gdbserver zastaven')}
   catch(error){toast(error.message);await refreshDevDebug()}
  };
 });
}
async function refreshDevDebug(){try{const response=await fetch(`/api/dev/debug?workspace=${encodeURIComponent(filesWorkspace())}`,{cache:'no-store'}),value=await response.json();if(!response.ok)throw new Error(value.error||'GDB stav nelze načíst.');renderDevDebug(value.components||[],!!value.local_client)}catch(error){$('dev-debug-components').innerHTML=`<span class="error">${esc(error.message)}</span>`}}
async function openGdbConsole(component){await closeGdbConsole();if(!gdbTerm){gdbTerm=new Terminal({convertEol:true,cursorBlink:true,fontFamily:fonts.system,fontSize:12,theme:{background:'#0b100f',foreground:'#d5ddd8',cursor:'#ff6a3d'}});gdbFit=new FitAddon.FitAddon();gdbTerm.loadAddon(gdbFit);gdbTerm.open($('dev-gdb-terminal'));gdbTerm.onData(data=>{if(gdbSession)void post('/api/dev/gdb/session',{action:'write',session:gdbSession,data})})}$('dev-gdb-console').classList.remove('hidden');$('dev-gdb-title').textContent=`GDB · ${component}`;$('dev-gdb-state').textContent='připojuji…';gdbTerm.clear();requestAnimationFrame(()=>gdbFit.fit());try{const response=await post('/api/dev/gdb/session',{action:'open',workspace:filesWorkspace(),component}),value=await response.json();if(!response.ok)throw new Error(value.error||'GDB konzoli nelze otevřít.');gdbSession=value.session;$('dev-gdb-state').textContent='připojeno';void readGdbConsole()}catch(error){gdbTerm.writeln(`\x1b[31m${error.message}\x1b[0m`);$('dev-gdb-state').textContent='chyba'}}
async function readGdbConsole(){if(gdbReading||!gdbSession)return;gdbReading=true;try{while(gdbSession){const response=await fetch(`/api/dev/gdb/session?session=${encodeURIComponent(gdbSession)}`,{cache:'no-store'}),value=await response.json();if(!response.ok)throw new Error(value.error||'GDB relace skončila.');if(value.data)gdbTerm.write(value.data);if(value.closed){gdbSession='';$('dev-gdb-state').textContent='ukončeno';break}}}catch(error){if(gdbSession)gdbTerm.writeln(`\r\n\x1b[31m${error.message}\x1b[0m`);gdbSession='';$('dev-gdb-state').textContent='odpojeno'}finally{gdbReading=false}}
async function closeGdbConsole(){const session=gdbSession;gdbSession='';if(session)try{await post('/api/dev/gdb/session',{action:'close',session})}catch(error){}$('dev-gdb-console').classList.add('hidden')}
$('dev-gdb-close').onclick=closeGdbConsole;
initDevApi();initDevPairing();
document.querySelectorAll('.dev-patch').forEach(card=>{const input=card.querySelector('input[type=file]'),textarea=card.querySelector('textarea'),editor=document.createElement('div'),lines=document.createElement('pre'),code=document.createElement('div'),highlight=document.createElement('pre'),name=document.createElement('input'),mode=document.createElement('label'),applied=document.createElement('input'),applyButton=card.querySelector('[data-dev-apply]');editor.className='dev-editor';lines.className='dev-lines';code.className='dev-code';highlight.className='dev-highlight';name.dataset.devName='';name.className='dev-patch-name';name.placeholder='Název patche (volitelné)';applied.type='checkbox';applied.dataset.devApplied='';mode.className='dev-applied-mode';mode.append(applied,document.createTextNode(' už je aplikovaný'));textarea.before(editor);editor.append(lines,code);code.append(highlight,textarea);card.querySelector('.dev-patch-tools').prepend(name,mode);applied.onchange=()=>applyButton.textContent=applied.checked?'Uložit pro revert':'Aplikovat patch';textarea.oninput=()=>updateDevLineNumbers(card);textarea.onscroll=()=>{lines.scrollTop=textarea.scrollTop;highlight.scrollTop=textarea.scrollTop;highlight.scrollLeft=textarea.scrollLeft};updateDevLineNumbers(card);card.querySelector('[data-dev-load]').onclick=()=>input.click();input.onchange=async()=>{await loadDevPatch(card,input.files[0]);if(!name.value)name.value=input.files[0]?.name.replace(/\.(diff|patch)$/i,'')||'';input.value=''};applyButton.onclick=()=>applyDevPatch(card)});
$('dev-revert-all').onclick=async()=>{if(!confirm('Vrátit všechny dosud aplikované patche v opačném pořadí?'))return;try{const value=await devOperation('revert-all');toast(`Vráceno patchů: ${value.result.reverted}`)}catch(error){toast(error.message)}};
